import React, { useState, useEffect, useRef } from "react";
import { AnimatePresence, motion, useInView, useAnimation } from "framer-motion";
import "./index.css";
import Navbar from "./Navbar";
import Hero from "./Hero";
import About from "./About";
import Collections from "./Collections";
import WhyChooseUs from "./WhyChooseUs";
import Testimonials from "./Testimonials";
import Contact from "./Contact";
import Footer from "./Footer";
import FloatingButtons from "./FloatingButtons";
import QuoteModal from "./QuoteModal";
import TrustedBy from "./TrustedBy";
import EventDate from "./EventDate";
import BehindScenes from "./BehindScenes";
import MoodBoard from "./MoodBoard";
import LiveCounter from "./LiveCounter";
import BeforeAfter from "./BeforeAfter";
import CountdownTimer from "./CountdownTimer";
import WeddingVision from "./WeddingVision";
import { ContainerScroll, ParallaxImage } from "./ContainerScroll";

// Scroll reveal animation variants
export const fadeInUp = {
  hidden: { opacity: 0, y: 40 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.7, ease: [0.25, 0.46, 0.45, 0.94] } }
};

export const fadeInLeft = {
  hidden: { opacity: 0, x: -40 },
  visible: { opacity: 1, x: 0, transition: { duration: 0.7, ease: [0.25, 0.46, 0.45, 0.94] } }
};

export const fadeInRight = {
  hidden: { opacity: 0, x: 40 },
  visible: { opacity: 1, x: 0, transition: { duration: 0.7, ease: [0.25, 0.46, 0.45, 0.94] } }
};

export const scaleIn = {
  hidden: { opacity: 0, scale: 0.9 },
  visible: { opacity: 1, scale: 1, transition: { duration: 0.5, ease: "easeOut" } }
};

// Stagger children animation
export const staggerContainer = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.1, delayChildren: 0.1 }
  }
};

// Page transition wrapper
export function AnimatedSection({ children, className = "", variants = fadeInUp }) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-80px" });
  const controls = useAnimation();

  useEffect(() => {
    if (isInView) {
      controls.start("visible");
    }
  }, [isInView, controls]);

  return (
    <motion.div
      ref={ref}
      initial="hidden"
      animate={controls}
      variants={variants}
      className={className}
    >
      {children}
    </motion.div>
  );
}

function App() {
  const [isQuoteModalOpen, setIsQuoteModalOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isMoodBoardOpen, setIsMoodBoardOpen] = useState(false);

  const handleOpenQuote = () => setIsQuoteModalOpen(true);
  const handleCloseQuote = () => setIsQuoteModalOpen(false);
  const handleOpenMoodBoard = () => setIsMoodBoardOpen(true);
  const handleCloseMoodBoard = () => setIsMoodBoardOpen(false);

  // Page load animation
  useEffect(() => {
    const timer = setTimeout(() => setIsLoading(false), 2500);
    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="app" style={{ background: "#ffffff", minHeight: "100vh" }}>
      {/* Loading Screen */}
      <AnimatePresence>
        {isLoading && (
          <motion.div
            initial={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1, ease: "easeInOut" }}
            className="fixed inset-0 z-[9999] flex items-center justify-center"
            style={{ background: "#ffffff" }}
          >
            <motion.div
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={{ duration: 0.6 }}
              className="text-center"
            >
              <h1 className="serif gold-shimmer text-4xl md:text-6xl mb-6" style={{ fontWeight: 400 }}>
                D SAJAWAT
              </h1>
              <motion.div
                initial={{ width: 0 }}
                animate={{ width: 120 }}
                transition={{ duration: 1, delay: 0.3 }}
                className="h-0.5 mx-auto rounded-full"
                style={{ background: "linear-gradient(90deg, transparent, #d4af37, transparent)" }}
              />
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <Navbar onOpenQuote={handleOpenQuote} />

      {/* Mood Board FAB Button */}
      <motion.button
        initial={{ scale: 0 }}
        animate={{ scale: 1 }}
        transition={{ delay: 3, type: "spring" }}
        onClick={handleOpenMoodBoard}
        className="fixed bottom-24 left-6 z-50 px-4 py-3 rounded-full flex items-center gap-2"
        style={{
          background: "linear-gradient(135deg, #d4af37, #f4d77a)",
          boxShadow: "0 4px 20px rgba(212,175,55,0.4)",
        }}
      >
        <span className="text-lg">🎨</span>
        <span className="text-sm font-semibold hidden md:inline" style={{ color: "#1a080a" }}>
          Create Mood Board
        </span>
      </motion.button>

      <main>
        {/* Hero Section with Container Scroll Animation */}
        <ContainerScroll
          titleComponent={
            <div className="text-center px-4">
              <p className="text-sm md:text-base uppercase tracking-[0.3em] mb-4" style={{ color: "#d4af37" }}>
                Premium Wedding & Event Fabrics
              </p>
              <h2 className="serif text-4xl md:text-6xl lg:text-7xl font-normal" style={{ color: "#1a080a" }}>
                Crafted with Elegance
              </h2>
              <p className="mt-4 text-base md:text-lg max-w-xl mx-auto" style={{ color: "rgba(26,8,10,0.7)" }}>
                Discover our exquisite collection of premium fabrics designed to transform your special occasions into timeless memories.
              </p>
            </div>
          }
        >
          <div className="relative w-full" style={{ height: "80vh", background: "#ffffff" }}>
            <Hero onOpenQuote={handleOpenQuote} />
          </div>
        </ContainerScroll>

        {/* Trusted By Section */}
        <motion.div
